toolScript:
// --- Core Application Logic ---
        const canvas = document.getElementById('stick-canvas');
        const ctx = canvas.getContext('2d');
        const deviceStatus = document.getElementById('device-status');
        const controllerName = document.getElementById('controller-name');
        const gamepadIdShort = document.getElementById('gamepad-id-short');
        let gamepadIndex = null;
        let selectedStick = 0; // 0 for Left, 1 for Right
        let animationFrameId;
        // Metrics
        let maxSnapback = 0;
        let jitterSamples = [];
        const JITTER_WINDOW = 60; // Approx 1 second of data at 60fps
        // Polling Rate Vars
        let pollCount = 0;
        let lastPollCheck = 0;
        let frameTime = 0;
        // Snapback Physics State
        let prevPos = { x: 0, y: 0 };
        let wasExtended = false;
        let releaseVector = { x: 0, y: 0 };
        let trail = []; // Visual trail for snapback
        // Event Listeners
        window.addEventListener("gamepadconnected", (e) => {
            gamepadIndex = e.gamepad.index;
            const gp = e.gamepad;
            // Visual Updates
            deviceStatus.className = "flex items-center gap-2 justify-center py-2 px-4 rounded-full bg-emerald-100 text-emerald-700 border border-emerald-200";
            deviceStatus.innerHTML = `<div class="w-2 h-2 bg-emerald-500 rounded-full"></div><span class="text-[10px] font-bold uppercase tracking-widest">Connected</span>`;
            controllerName.innerText = gp.id.substring(0, 35) + (gp.id.length > 35 ? '...' : '');
            gamepadIdShort.innerText = "Active";
            // Start Loop
            requestAnimationFrame(updateLoop);
        });
        window.addEventListener("gamepaddisconnected", () => {
            gamepadIndex = null;
            // Visual Updates
            deviceStatus.className = "flex items-center gap-2 justify-center py-2 px-4 rounded-full bg-rose-100 text-rose-700 border border-rose-200";
            deviceStatus.innerHTML = `<div class="w-2 h-2 bg-rose-500 rounded-full"></div><span class="text-[10px] font-bold uppercase tracking-widest">Disconnected</span>`;
            controllerName.innerText = "No Device Detected";
            gamepadIdShort.innerText = "None";
            cancelAnimationFrame(animationFrameId);
            clearCanvas();
        });
        function setStick(idx) {
            selectedStick = idx;
            document.getElementById('btn-left').classList.toggle('active', idx === 0);
            document.getElementById('btn-right').classList.toggle('active', idx === 1);
            resetStats();
        }
        function resetStats() {
            maxSnapback = 0;
            jitterSamples = [];
            trail = [];
            document.getElementById('snap-val').innerText = "0.0%";
            document.getElementById('snap-val').className = "metric-value text-rose-600";
            document.getElementById('jitter-val').innerText = "0.000";
            document.getElementById('center-val').innerText = "0.0%";
        }
        function updateLoop(timestamp) {
            const gamepads = navigator.getGamepads();
            if (!gamepads || !gamepads[gamepadIndex]) return;
            const gp = gamepads[gamepadIndex];
            // Handle Timestamp Display
            if (gp.timestamp) {
                document.getElementById('timestamp-disp').innerText = gp.timestamp.toFixed(2);
            }
            // Polling Rate Calc
            pollCount++;
            if (timestamp - lastPollCheck > 1000) {
                document.getElementById('poll-rate-disp').innerText = `${pollCount} Hz`;
                pollCount = 0;
                lastPollCheck = timestamp;
            }
            // Get Input
            let x = 0, y = 0;
            if (selectedStick === 0) { // Left Stick
                x = gp.axes[0] || 0;
                y = gp.axes[1] || 0;
            } else { // Right Stick
                x = gp.axes[2] || 0;
                y = gp.axes[3] || 0;
            }
            // --- LOGIC ---
            const magnitude = Math.sqrt(x * x + y * y);
            // 1. Centering Error
            if (magnitude < 0.1 && magnitude > 0.001) {
                const err = (magnitude * 100).toFixed(2) + "%";
                document.getElementById('center-val').innerText = err;
            } else if (magnitude <= 0.001) {
                document.getElementById('center-val').innerText = "0.0%"; // Perfect center
            }
            // 2. Snapback Detection
            detectSnapback(x, y, magnitude);
            // 3. Jitter
            detectJitter(x, y, magnitude);
            // --- RENDER ---
            drawVisualizer(x, y);
            document.getElementById('coord-x').innerText = `X: ${x.toFixed(5)}`;
            document.getElementById('coord-y').innerText = `Y: ${y.toFixed(5)}`;
            prevPos = { x, y };
            animationFrameId = requestAnimationFrame(updateLoop);
        }
        function detectSnapback(x, y, mag) {
            // State 1: Extended
            if (mag > 0.9) {
                wasExtended = true;
                releaseVector = { x, y };
                trail = []; // Reset visual trail when extended
            }
            // State 2: Returning / Snapping
            if (wasExtended) {
                trail.push({ x, y }); // Add to trail
                // If we are near center
                if (mag < 0.15) {
                    const dot = x * releaseVector.x + y * releaseVector.y;
                    // Dot product < 0 means opposite direction (Overshoot)
                    if (dot < -0.02) {
                        const overshootPct = (mag * 100);
                        if (overshootPct > maxSnapback) {
                            maxSnapback = overshootPct;
                            const el = document.getElementById('snap-val');
                            el.innerText = maxSnapback.toFixed(1) + "%";
                            if (maxSnapback > 15) {
                                el.classList.add('jitter-alert');
                            }
                        }
                    }
                }
            }
            // Limit trail size
            if (trail.length > 50) trail.shift();
        }
        function detectJitter(x, y, mag) {
            // Only calculate jitter if stick is very still
            const delta = Math.sqrt(Math.pow(x - prevPos.x, 2) + Math.pow(y - prevPos.y, 2));
            if (delta < 0.05) { // Threshold for "Intentional Movement"
                jitterSamples.push(delta);
                if (jitterSamples.length > JITTER_WINDOW) jitterSamples.shift();
                const sum = jitterSamples.reduce((a, b) => a + b, 0);
                const avg = (sum / jitterSamples.length) * 10; // Scale for readability
                document.getElementById('jitter-val').innerText = avg.toFixed(4);
            }
        }
        function drawVisualizer(x, y) {
            const w = canvas.width;
            const h = canvas.height;
            const cx = w / 2;
            const cy = h / 2;
            const r = (w / 2) - 20;
            ctx.clearRect(0, 0, w, h);
            // Outer Circle
            ctx.beginPath();
            ctx.arc(cx, cy, r, 0, 2 * Math.PI);
            ctx.strokeStyle = '#334155';
            ctx.lineWidth = 2;
            ctx.stroke();
            // Inner Deadzone (Standard 10%)
            ctx.beginPath();
            ctx.arc(cx, cy, r * 0.1, 0, 2 * Math.PI);
            ctx.strokeStyle = '#475569';
            ctx.setLineDash([4, 4]);
            ctx.stroke();
            ctx.setLineDash([]);
            // Crosshair
            ctx.beginPath();
            ctx.moveTo(cx - 10, cy); ctx.lineTo(cx + 10, cy);
            ctx.moveTo(cx, cy - 10); ctx.lineTo(cx, cy + 10);
            ctx.strokeStyle = '#64748b';
            ctx.stroke();
            // Draw Trail (Snapback history)
            if (trail.length > 1) {
                ctx.beginPath();
                ctx.moveTo(cx + trail[0].x * r, cy + trail[0].y * r);
                for (let i = 1; i < trail.length; i++) {
                    ctx.lineTo(cx + trail[i].x * r, cy + trail[i].y * r);
                }
                ctx.strokeStyle = 'rgba(239, 68, 68, 0.6)'; // Red trail
                ctx.lineWidth = 3;
                ctx.stroke();
            }
            // Current Stick Position
            const px = cx + (x * r);
            const py = cy + (y * r);
            // Stick Line
            ctx.beginPath();
            ctx.moveTo(cx, cy);
            ctx.lineTo(px, py);
            ctx.strokeStyle = '#8b5cf6';
            ctx.lineWidth = 2;
            ctx.stroke();
            // Stick Head
            ctx.beginPath();
            ctx.arc(px, py, 10, 0, 2 * Math.PI);
            ctx.fillStyle = '#8b5cf6';
            ctx.shadowBlur = 15;
            ctx.shadowColor = 'rgba(139, 92, 246, 0.6)';
            ctx.fill();
            ctx.shadowBlur = 0;
        }
        function clearCanvas() {
            const w = canvas.width;
            const h = canvas.height;
            ctx.clearRect(0, 0, w, h);
            // Draw placeholder UI
            const cx = w / 2, cy = h / 2, r = (w / 2) - 20;
            ctx.beginPath();
            ctx.arc(cx, cy, r, 0, 2 * Math.PI);
            ctx.strokeStyle = '#334155';
            ctx.stroke();
        }
